.tie_id AS tie FROM jac_snb_message_mirror m WHERE m.creator_id = ? AND m.arch_type = ? AND m.creation_date <= ? ORDER BY m.creation_date DESC, m.tie_id ASC LIMIT 20) UNION ALL (SELECT m.id, m.creation_date AS ord, m.tie_id AS tie FROM jac_snb_message_mirror m WHERE m.creator_id = ? AND m.arch_type = ? AND m.creation_date <= ? ORDER BY m.creation_date DESC, m.tie_id ASC LIMIT 20) UNION ALL (SELECT m.id, m.creation_date AS ord, m.tie_id AS tie FROM jac_snb_message_mirror m WHERE m.creator_id = ? AND m.arch_type = ? AND m.creation_date <= ? ORDER BY m.creation_date DESC, m.tie_id ASC LIMIT 20) UNION ALL (SELECT m.id, m.creation_date AS ord, m.tie_id AS tie FROM jac_snb_message_mirror m WHERE m.creator_id = ? AND m.arch_type = ? AND m.creation_date <= ? ORDER BY m.creation_date DESC, m.tie_id ASC LIMIT 20) UNION ALL (SELECT m.id, m.creation_date AS ord, m.tie_id AS tie FROM jac_snb_message_mirror m WHERE m.creator_id = ? AND m.arch_type = ? AND m.creation_date <= ? ORDER BY m.creation_date DESC, m.tie_id ASC LIMIT 20) UNION ALL (SELECT m.id, m.creation_date AS ord, m.tie_id AS tie FROM jac_snb_message_mirror m WHERE m.creator_id = ? AND m.arch_type = ? AND m.creation_date <= ? ORDER BY m.creation_date DESC, m.tie_id ASC LIMIT 20) UNION ALL (SELECT m.id, m.creation_date AS ord, m.tie_id AS tie FROM jac_snb_message_mirror m WHERE m.creator_id = ? AND m.arch_type = ? AND m.creation_date <= ? ORDER BY m.creation_date DESC, m.tie_id ASC LIMIT 20) UNION ALL (SELECT m.id, m.creation_date AS ord, m.tie_id AS tie FROM jac_snb_message_mirror m WHERE m.creator_id = ? AND m.arch_type = ? AND m.creation_date <= ? ORDER BY m.creation_date DESC, m.tie_id ASC LIMIT 20) UNION ALL (SELECT m.id, m.creation_date AS ord, m.tie_id AS tie FROM jac_snb_message_mirror m WHERE m.creator_id = ? AND m.arch_type = ? AND m.creation_date <= ? ORDER BY m.creation_date DESC, m.tie_id ASC LIMIT 20) ) u ORDER BY ord DESC, tie ASC LIMIT 20
